import{_ as n}from"./chunks/run-changes.BxnGjCua.js";import{_ as s,C as r,o as i,c as o,j as t,a as h,E as l,ak as d}from"./chunks/framework.sV-XtlWr.js";const y=JSON.parse('{"title":"What changed in a run","description":"What changed in a run against its baseline: new failures, fixed tests, new flakes, the largest duration changes and the commits in between.","frontmatter":{"title":"What changed in a run","description":"What changed in a run against its baseline: new failures, fixed tests, new flakes, the largest duration changes and the commits in between.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/run-changes.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/run-changes.html"}],["meta",{"property":"og:title","content":"What changed in a run | Piwi Dashboard"}],["meta",{"property":"og:description","content":"What changed in a run against its baseline: new failures, fixed tests, new flakes, the largest duration changes and the commits in between."}]]},"headers":[],"relativePath":"features/run-changes.md","filePath":"features/run-changes.md","lastUpdated":1791216273000}'),u={name:"features/run-changes.md"};function c(g,e,p,m,f,b){const a=r("Needs");return i(),o("div",null,[e[0]||(e[0]=t("h1",{id:"what-changed-in-a-run",tabindex:"-1"},[h("What changed in a run "),t("a",{class:"header-anchor",href:"#what-changed-in-a-run","aria-label":'Permalink to "What changed in a run"'},"​")],-1)),l(a,{reporter:""}),e[1]||(e[1]=d('<p>The <strong>Changes</strong> tab on a run compares it against <strong>one baseline</strong> and tells you what moved: which tests newly started failing, which got fixed, and what landed between the two. It&#39;s the fastest way to answer &quot;did my push break this, or was it already red?&quot;</p><h2 id="the-baseline" tabindex="-1">The baseline <a class="header-anchor" href="#the-baseline" aria-label="Permalink to &quot;The baseline&quot;">​</a></h2><p>Every section reads the <strong>same baseline</strong>, so the &quot;new failures&quot; count is computed once and used throughout. The selector at the top says which run it is, which branch and environment that run is on, and <strong>why it was chosen</strong>.</p><p>By default the baseline is the last passing full run chosen by the <a href="/guide/concepts.html#baseline-last-green-run">baseline rule</a>: same environment first, then same branch, base branch, any branch. The line under the selector spells out the rung that applied, for example <em>&quot;No passing staging run exists on feature/x; the last passing run on the default branch main in staging.&quot;</em></p><h3 id="when-no-earlier-run-passed" tabindex="-1">When no earlier run passed <a class="header-anchor" href="#when-no-earlier-run-passed" aria-label="Permalink to &quot;When no earlier run passed&quot;">​</a></h3><p>A project that has never had a green run still gets a comparison. When no earlier full run passed, the tab walks the same ladder again for the <strong>last failed run</strong> and says so: <em>&quot;No earlier full run passed; the last failed run on feature/x in staging.&quot;</em> The sections read the same way against it: <strong>New failures</strong> are the tests that passed in that run and fail here, <strong>Still failing</strong> the ones that failed in both. Timed-out and interrupted runs stopped before the suite ended, so they are never picked automatically.</p><p>Only the Changes tab and the MCP <code>get_run_insights</code> tool take a failed run. The stored regression signals, the <a href="/guide/ci.html#blocking-a-merge">CI gate</a> and <a href="/features/pr-feedback.html">pull-request feedback</a> keep comparing with a passing run, so their verdicts never rest on a run that was itself red.</p><p>When nothing qualifies (the earlier runs are partial, timed out or interrupted), the tab says so and offers the earlier runs to pick from. On the project&#39;s first finished run, it says there is nothing earlier yet.</p><h3 id="picking-another-baseline" tabindex="-1">Picking another baseline <a class="header-anchor" href="#picking-another-baseline" aria-label="Permalink to &quot;Picking another baseline&quot;">​</a></h3><p>Two ways to compare against something else:</p><ul><li><strong>Base branch</strong> — take the baseline from one branch only: its last passing run, else its last failed run, same environment first. The list offers every branch with an earlier full run that passed or failed, so it appears once a branch other than this run&#39;s own has one. Deep-linkable as <code>?baseBranch=&lt;name&gt;</code>.</li><li><strong>Run</strong> — compare against one earlier run, whatever its branch, environment or outcome. The list shows the 50 runs before this one, each with its branch, environment, start time and outcome, partial runs marked; type a branch or environment name to filter it. Deep-linkable as <code>?baseline=&lt;runId&gt;</code>, so a link to a comparison reopens the same two runs. <strong>Previous run</strong> is the shortcut for the run just before this one.</li></ul><p><strong>Automatic</strong> returns to the default choice. The same options exist on the REST API (see the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>), where <code>earlierRuns</code> lists the runs that can be passed as <code>baseline</code>, and on the MCP <code>get_run_insights</code> tool (<code>baseBranch</code>).</p><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><ul><li><strong>New failures</strong> — passed in the baseline, failing here.</li><li><strong>Fixed</strong> — failed in the baseline, passing here.</li><li><strong>Still failing</strong> — failing in both.</li><li><strong>Newly flaky / passed on retry</strong> — passed here but needed a retry.</li><li><strong>Slower / faster</strong> — the ten largest duration changes each way.</li><li><strong>Commits since the baseline</strong> — the commit range, a copyable <code>git log</code> command and, when the SCM host is known, a link to the commits.</li><li><strong>Environment changes</strong> — the fields that differ, in <em>This run</em> / <em>Baseline</em> columns.</li></ul><figure><img src="'+n+'" alt="Run Changes tab showing the baseline selector, the tests that newly started failing, the ones that got fixed, and the commits landed since the baseline"><figcaption>The Changes tab on a run, read against one baseline — new failures, fixed tests, and the commits landed since.</figcaption></figure><p>Comparing two runs is also how the <a href="./ui-overview.html#test-run-detail">run comparison</a> works: select two runs on the project&#39;s Runs tab and the newer one opens on its Changes tab with the older as its baseline.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/regression-or-flaky.html">Regression or flake?</a>: the Changes tab, used to decide whether one red test is new</li><li><a href="./branches.html#branch-aware-baselines">Branches</a> — why the default baseline is the same-branch run</li><li><a href="./flaky-tests.html">Flaky tests</a> — the per-project flaky, regression and spec-health signals</li><li><a href="./failure-clusters.html">Failure clusters &amp; the inbox</a> — the failures grouped by cause</li><li><a href="./timeline-markers.html">Timeline markers</a> — annotate the trend charts with real-world events</li></ul>',18))])}const _=s(u,[["render",c]]);export{y as __pageData,_ as default};
